using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person roundTripped = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {roundTripped}");

// 2. TryGetTypeInfo() — probe without throwing.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");

// Probe for a type the resolver doesn't know about
// (use a resolver that only handles Person to force a miss).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver())
};

if (limited.TryGetTypeInfo(typeof(int), out _))
    Console.WriteLine("int metadata found (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo(int) returned false — no exception thrown");

record Person(string Name, int Age);

// A resolver that only provides metadata for Person.
class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

